interface PNCounterState {
  increments: Record<string, number>; // regionId -> monotonic count
  decrements: Record<string, number>; // regionId -> monotonic count
}

// Commutative, Associative, Idempotent Merge across Active-Active Regions
function mergePNCounter(local: PNCounterState, remote: PNCounterState): PNCounterState {
  const merged: PNCounterState = { increments: {}, decrements: {} };
  const regions = new Set([
    ...Object.keys(local.increments), ...Object.keys(remote.increments),
    ...Object.keys(local.decrements), ...Object.keys(remote.decrements),
  ]);
  for (const r of regions) {
    merged.increments[r] = Math.max(local.increments[r] ?? 0, remote.increments[r] ?? 0);
    merged.decrements[r] = Math.max(local.decrements[r] ?? 0, remote.decrements[r] ?? 0);
  }
  return merged;
}

class FencedStorageEngine {
  private highestSeenEpoch = 0;

  public applyWrite(epochToken: number, key: string, value: Uint8Array): void {
    if (epochToken < this.highestSeenEpoch) {
      throw new StaleLeaderFencedError(
        'Rejected zombie write from old primary with epoch ' + epochToken +
        ' (current epoch: ' + this.highestSeenEpoch + ')'
      );
    }
    this.highestSeenEpoch = epochToken;
    this.commitToDisk(key, value);
  }
}

